DROP TABLE IF EXISTS `player_lyra`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `player_lyra` (
  `player_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `player_name` varchar(20) NOT NULL DEFAULT '',
  `upper_name` varchar(20) NOT NULL DEFAULT '',
  `password` varchar(20) NOT NULL DEFAULT '',
  `focus_stat` int(10) unsigned DEFAULT '0',
  `avatar` int(10) unsigned NOT NULL DEFAULT '0',
  `avatar2` int(10) unsigned NOT NULL DEFAULT '0',
  `xp` int(10) unsigned DEFAULT '0',
  `acct_type` int(10) unsigned NOT NULL DEFAULT '0',
  `logged_in` int(10) unsigned DEFAULT '0',
  `num_logins` int(10) unsigned DEFAULT '0',
  `time_online` int(10) unsigned DEFAULT '0',
  `last_login` int(10) unsigned DEFAULT '0',
  `killer_id` int(10) unsigned DEFAULT '0',
  `billing_id` int(10) unsigned NOT NULL DEFAULT '0',
  `real_name` varchar(64) NOT NULL DEFAULT '',
  `email` varchar(64) NOT NULL DEFAULT '',
  `room_id` int(10) unsigned DEFAULT '0',
  `level_id` int(10) unsigned DEFAULT '0',
  `last_login_date` date DEFAULT '0000-00-00',
