  `MaxDreamsoul` int(10) unsigned NOT NULL DEFAULT '20',
  `MaxResilience` int(10) unsigned NOT NULL DEFAULT '10',
  `MaxLucidity` int(10) unsigned NOT NULL DEFAULT '10',
  `MaxWillpower` int(10) unsigned NOT NULL DEFAULT '10',
  `MaxInsight` int(10) unsigned NOT NULL DEFAULT '10',
